MATCH (v:PlantItem:GateValve {unit_id: '214'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'P-44501B'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(i:PlantItem {loop_tag: 'PI-59035'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem {tag: 'P-33901B'}), (v:Valve), (e:Equipment)
WHERE EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-48601B'}), (b:PlantItem {tag: 'M-48701'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x.tag <> 'BFV-486001')+ (b)
} AS reachable

MATCH (head:ProcessInstrumentationFunction {loop_tag: 'TIAH-170015'})
MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(head)
RETURN DISTINCT equipment.tag AS tag ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-35801'}), (b:PlantItem {tag: 'D-35801'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v.tag) AS valve_count, collect(DISTINCT v.tag) AS valve_tags

MATCH (a:PlantItem {tag: 'P-35801'}), (b:PlantItem {tag: 'D-35801'})
CALL {
  WITH a
  MATCH (a)-[:line_to*1..]->(v:Valve)
  RETURN collect(DISTINCT v.tag) AS downstreamTags
}
CALL {
  WITH b
  MATCH (v:Valve)-[:line_to*1..]->(b)
  RETURN collect(DISTINCT v.tag) AS upstreamTags
}
WITH [tag IN downstreamTags WHERE tag IN upstreamTags] AS valveTags
RETURN size(valveTags) AS valve_count, valveTags AS valve_tags

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)-[:send_signal_to*0..]->(h:ProcessInstrumentationFunction {loop_tag: 'PI-258010'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem:Valve {tag: 'V-54101'})-[:line_to*1..]->(valve:PlantItem:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)
WHERE EXISTS {
  (sensor)-[:send_signal_to*0..]->(:ProcessInstrumentationFunction {loop_tag: 'TI-6050'})
}
RETURN DISTINCT e.tag AS tag
ORDER BY tag

MATCH (e:PlantItem {tag: 'P-18901'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(loop:ProcessInstrumentationFunction {loop_tag: 'LIC-109003'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (loop:PlantItem {loop_tag: 'HS-400001'})-[:send_signal_to*]->(actuator:ActuatingFunction)-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-103'}), (b:PlantItem {tag: 'K-1201'}), (v:Valve {tag: 'FV-1010'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y <> v)+ (b)
       } AS reachable_without_valve

MATCH (a:PlantItem {tag: 'TK-103'}), (b:PlantItem {tag: 'K-1201'}), (v:Valve {tag: 'FV-1010'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y <> v)+ (b)
       } AS reachable_without_valve

MATCH (source:PlantItem {tag: 'P-37801A'}), (v:PlantItem:Valve)
WHERE EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag
